+    public void setNextDocId(int docId) throws IOException {
+        if (input == null) {
+            return;
+        }
+        int currentDoc = input.docID();
+        if (currentDoc == NO_MORE_DOCS || docId < currentDoc) {
+            vector = null;
+        } else if (docId == currentDoc) {
+            vector = input.binaryValue();
